// --- Hand-written renderer (see this file's header comment) -------------

/** Linear scan through BITFONT_GLYPHS for ascii `c`. Returns NULL if `c`
 * isn't one of the covered glyphs (see bitfont.h's own header comment).
 * Linear because the table is ~16 entries -- a lookup table wouldn't be
 * meaningfully faster and would need the caller to bounds-check ascii
 * range first. */
static const BitfontGlyph *bitfont_glyph_lookup(char c) {
  for (int32_t i = 0; i < BITFONT_GLYPH_COUNT; i++) {
    if (BITFONT_GLYPHS[i].ascii == (int32_t)(unsigned char)c) return &BITFONT_GLYPHS[i];
  }
  return NULL;
}

void bitfont_draw_string(struct Graphics2D *g, const char *s, int32_t x, int32_t y) {
  int32_t cursor_x = x;
  for (const char *p = s; *p; p++) {
    const BitfontGlyph *gl = bitfont_glyph_lookup(*p);
    if (!gl) {
      // Fall back to space's advance (matches vfont's "advance, draw
      // nothing" behaviour for unsupported chars).
      const BitfontGlyph *sp = bitfont_glyph_lookup(' ');
      if (sp) cursor_x += sp->advance;
      continue;
    }
    // Walk this glyph's CELL_W * CELL_H bit grid, plot one 1x1 quad per set
    // bit. Bits packed LSB-first, row-major. gfx_fill_rect appends one 2-
    // triangle quad per call -- cheap since a glyph is <= 13x16 = 208 bits
    // and each character averages maybe 40-60 on-bits, so ~60 quads per
    // digit is negligible for the handful of HUD numbers per frame.
    for (int32_t row = 0; row < BITFONT_CELL_H; row++) {
      for (int32_t col = 0; col < BITFONT_CELL_W; col++) {
        int32_t bit_index = gl->bit_offset + row * BITFONT_CELL_W + col;
        int32_t byte = bit_index >> 3;
        int32_t bit = bit_index & 7;
        if (BITFONT_BITS[byte] & (1 << bit)) {
          gfx_fill_rect(g, cursor_x + col, y + row, 1, 1);
        }
      }
    }
    cursor_x += gl->advance;
  }
}

int32_t bitfont_text_width(const char *s) {
  int32_t w = 0;
  for (const char *p = s; *p; p++) {
    const BitfontGlyph *gl = bitfont_glyph_lookup(*p);
    if (gl) w += gl->advance;
    else {
      const BitfontGlyph *sp = bitfont_glyph_lookup(' ');
      if (sp) w += sp->advance;
    }
  }
  return w;
}
